public class PassByValueVisualizer {

    public static void main(String[] args) {
        int primitiveVal = 100;
        Dog myDog = new Dog("Fido");

        // 1. Demonstrate primitive pass-by-value
        modifyPrimitive(primitiveVal);
        System.out.println("After modifyPrimitive: " + primitiveVal); // Prints 100 (Unchanged)

        // 2. Demonstrate object mutation (sharing the same heap object)
        mutateObject(myDog);
        System.out.println("After mutateObject: " + myDog.getName()); // Prints "Rex" (Mutated!)

        // 3. Demonstrate object reassignment (proving it is NOT pass-by-reference)
        reassignObject(myDog);
        System.out.println("After reassignObject: " + myDog.getName()); // Still prints "Rex" (Unchanged by reassignment)
    }

    private static void modifyPrimitive(int value) {
        value = 500; // Only changes the local stack copy
    }

    private static void mutateObject(Dog dog) {
        dog.setName("Rex"); // Modifies the object on the heap that both references point to
    }

    private static void reassignObject(Dog dog) {
        dog = new Dog("Max"); // Reassigns local parameter to a new heap object; caller's reference is untouched
    }

    static class Dog {
        private String name;
        public Dog(String name) { this.name = name; }
        public String getName() { return name; }
        public void setName(String name) { this.name = name; }
    }
}
